const raw = $json.choices?.[0]?.message?.content ?? '{}';

// Strip markdown code fences if the model added them despite instructions
let cleaned = raw.trim();
cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();

// Extract just the outermost {...} block in case there's stray text around it
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI did not return valid JSON. Raw response: ' + raw);
}

const tasks = Array.isArray(parsed.tasks) ? parsed.tasks : [];

const result = tasks
  .filter(t => t && t.task)
  .map(t => ({
    task: String(t.task).trim(),
    owner: t.owner ? String(t.owner).trim() : 'Unassigned',
    deadline: t.deadline ? String(t.deadline).trim() : 'Not specified',
    priority: ['High', 'Medium', 'Low'].includes(t.priority) ? t.priority : 'Medium'
  }));

return [{ json: { tasks: result } }];
